import{_ as a,o as t,c as r,a2 as o,j as n}from"./chunks/framework.Ddyno5UB.js";const m=JSON.parse('{"title":"1. Kubernetes Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"kubernetes/1-architecture.md","filePath":"kubernetes/1-architecture.md"}'),s={name:"kubernetes/1-architecture.md"},i={xmlns:"http://www.w3.org/2000/svg",width:"100%",height:"100",viewBox:"0 0 400 100",style:{background:"#f1f2f4",border:"1px solid #0969da","border-radius":"8px",margin:"20px 0"}};function l(c,e,u,d,h,p){return t(),r("div",null,[e[1]||(e[1]=o('<h1 id="_1-kubernetes-architecture" tabindex="-1">1. Kubernetes Architecture <a class="header-anchor" href="#_1-kubernetes-architecture" aria-label="Permalink to &quot;1. Kubernetes Architecture&quot;">​</a></h1><p>Kubernetes (K8s) is a distributed system that orchestrates containerized applications. Understanding its architecture is the first step to mastering it.</p><p>A Kubernetes cluster consists of two main parts:</p><ol><li><strong>The Control Plane</strong>: The brains of the cluster.</li><li><strong>Worker Nodes</strong>: The machines that run your actual workloads.</li></ol><h2 id="architecture-diagram" tabindex="-1">Architecture Diagram <a class="header-anchor" href="#architecture-diagram" aria-label="Permalink to &quot;Architecture Diagram&quot;">​</a></h2>',5)),(t(),r("svg",i,[...e[0]||(e[0]=[n("text",{x:"200",y:"55","font-family":"monospace","font-size":"14",fill:"#24292f","text-anchor":"middle"},"SVG Diagram Placeholder",-1)])])),e[2]||(e[2]=o('<h2 id="the-control-plane" tabindex="-1">The Control Plane <a class="header-anchor" href="#the-control-plane" aria-label="Permalink to &quot;The Control Plane&quot;">​</a></h2><p>The Control Plane manages the worker nodes and the Pods in the cluster.</p><ul><li><strong>kube-apiserver</strong>: The frontend of the control plane. All communication goes through here.</li><li><strong>etcd</strong>: Consistent and highly-available key value store used as Kubernetes&#39; backing store for all cluster data.</li><li><strong>kube-scheduler</strong>: Watches for newly created Pods with no assigned node, and selects a node for them to run on.</li><li><strong>kube-controller-manager</strong>: Runs controller processes (like node controllers, replica controllers).</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Never lose your <code>etcd</code> data! In a production cluster, ensure <code>etcd</code> is backed up regularly, as losing it means losing the state of your entire cluster.</p></div><h2 id="worker-nodes" tabindex="-1">Worker Nodes <a class="header-anchor" href="#worker-nodes" aria-label="Permalink to &quot;Worker Nodes&quot;">​</a></h2><p>Nodes are the physical or virtual machines that run your applications.</p><ul><li><strong>kubelet</strong>: An agent that runs on each node. It ensures that containers are running in a Pod.</li><li><strong>kube-proxy</strong>: A network proxy that runs on each node, maintaining network rules that allow network communication to your Pods.</li><li><strong>Container Runtime</strong>: The software that is responsible for running containers (e.g., containerd, CRI-O).</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>In managed Kubernetes services like EKS, GKE, or AKS, the cloud provider manages the Control Plane for you. You only manage the Worker Nodes.</p></div>',8))])}const b=a(s,[["render",l]]);export{m as __pageData,b as default};
